There are non-deterministic \CMSO[2]-transductions $\tau_1,\ldots,\tau_7$ such that: 
    \begin{enumerate}
        \item 
           For any laminar set system $(U,\mathcal{S})$, $\tau_1(U, \mathcal{S})$ is non-empty
           and every output in~$\tau_1(U, \mathcal{S})$ is a laminar tree $T$ of $(U,\mathcal{S})$ (\autoref{thm:transduce laminar tree});
        \item 
            For any graph $G$, $\tau_2(G)$ is non-empty
            and every output in~$\tau_2(G)$ is a modular decomposition $(T,F)$ of $G$ (\autoref{thm:transduce modular decomposition});
        \item 
            For any cograph $G$, $\tau_3(G)$ is non-empty
            and every output in~$\tau_3(G)$ is a cotree $(T,\lambda)$ of $G$ (\autoref{thm:transduce cotree});
        \item 
             For any graph $G$, $\tau_4(G)$ is non-empty
             and every output in~$\tau_4(G)$ is a split decomposition $(T,F)$ of $G$ (\autoref{thm:split});
        \item 
             For any graph $G$, $\tau_5(G)$ is non-empty
             and every output in~$\tau_5(G)$ is a bi-join decomposition $(T,F)$ of $G$ (\autoref{thm:bi-join1} and \autoref{thm:bi-join2});
        \item 
            For any weakly-partitive set system $(U,\mathcal{S})$, $\tau_6(U,\mathcal{S})$ is non-empty
            and every output in~$\tau_6(U,\mathcal{S})$ is a weakly-partitive tree $(T,\lambda,<)$ of $(U,\mathcal{S})$ (\autoref{thm:transduce weakly-partitive tree});
        \item 
            For any weakly-bipartitive set system $(U,\mathcal{B})$, $\tau_7(U,\mathcal{B})$ is non-empty
            and every output in~$\tau_7(U,\mathcal{B})$ is a weakly-bipartitive tree $(T,\lambda,<)$ of $(U,\mathcal{B})$ (\autoref{thm:transduce weakly-bipartitive tree}).
    \end{enumerate}

Given a \emph{directed graph}~$G$,
its sets of \emph{vertices} and \emph{edges}
are denoted by \defd{$V(G)$} and \defd{$E(G)$}, respectively.

By extension, a set family~$\mathcal{S}$ is \defd{laminar}
if $\left(\bigcup\mathcal{S}, \mathcal{S}\right)$ is a laminar set system
(note this also requires that~$\emptyset\notin\mathcal{S}$, $\bigcup\mathcal{S}\in\mathcal{S}$, and~$\{a\}\in\mathcal{S}$ for every~$a\in\bigcup\mathcal{S}$).

Given a $\Sigma$-structure~$\mathbb{A}$
and,
for some vocabulary~$\Gamma$,
a $\Gamma$-structure~$\mathbb{B}$,
we write~\defd{$\mathbb{A}\sqsubseteq\mathbb{B}$}
if~$\Sigma\subseteq\Gamma$,
$U_{\mathbb{A}}\subseteq U_{\mathbb{B}}$
and for each symbol~$Q$ in~$\Sigma$,
$Q_{\mathbb{A}}=Q_{\mathbb{B}}$.

The pair~$(\pi,\sigma)$ has \emph{unique request}
if every node~$x$ of~$T$ is requested at most once in~$(\pi,\sigma)$,
{\em i.e.}, there exists at most one~$s\in S$ such that~$x$ is $s$-requested in~$(\pi,\sigma)$.

We say that~$(A,B)$ \emph{identifies~$S$}
if there exists a pair~$(\pi,\sigma)$ identifying~$S$ with unique request
such that~$\pi(S)=A$ and~$\sigma(S)=B$.

A set system~$(U,\mathcal{S})$ is \defd{weakly-partitive} if
for every two overlapping sets~$X,Y\in\mathcal{S}$,
the sets~$X\cup Y$, $X\cap Y$, $X\setminus Y$, and~$Y\setminus X$ belong to~$\mathcal{S}$.

According to \autoref{thm:weakly-partitive tree},
    an inner node~$t$ is labeled~$\ensuremath{\mathsf{degenerate}}\xspace$
    if and only if\xspace,
    for every two children $s_1,s_2$ of $t$ the set $L(T_{s_1})\cup L(T_{s_2})$ is in $\mathcal{S}$. We can define this in \ensuremath{\operatorname{MSO}}\xspace using the following formula:
        $$\phi_{\ensuremath{\mathsf{degenerate}}\xspace}(x):=\forall y \forall z\Big(\big(\ensuremath{\mathsf{parent}}\xspace(x,y)\land \ensuremath{\mathsf{parent}}\xspace(x,z)\big)\rightarrow \ensuremath{\mathsf{SET}}\xspace\big(\ensuremath{\mathsf{leafset}}\xspace(y)\cup \ensuremath{\mathsf{leafset}}\xspace(z)\big)\Big).$$

Now, according to \autoref{thm:weakly-partitive tree},
    we have~$x<y<z$ or~$z<y<x$ exactly when~$x$, $y$, and~$z$ are three distinct children of some node~$t$
    and the three following properties are satisfied:
    \begin{enumerate}[nosep]
        \item $L(T_x)\cup L(T_z)$ is not a member of~$\mathcal{S}$;
        \item  there exists a member of~$\mathcal{S}$ which includes both~$L(T_x)$ and~$L(T_y)$ but excludes~$L(T_z)$;
        \item  there exists a member of~$\mathcal{S}$ which includes both~$L(T_y)$ and~$L(T_z)$ but excludes~$L(T_x)$.
    \end{enumerate}

Let~$G$ be a directed graph
and let~$M\subseteq V(G)$.
We say that~$M$ is a \defd{module (of~$G$)}
if for every $u\notin M$ and every $v,w\in M$,
${uv\in E(G)\!\iff\! uw\in E(G)}$
and~${vu\in E(G)\!\iff\! wu\in E(G)}$.

let~$T$ be the laminar tree induced by the weakly-partitive family~$\mathcal{M}$
            and let~$\mathbb{T}$ be the $\{\mathsf{ancestor}\}$-structure
            modeling it with~$U_{\mathbb{T}}=V(T)$ and~$L(T)=V(G)\subset U_{\mathbb{T}}$;

let~$F$ be the $\mathsf{m}$-edge relation,
            namely the subset of~$V(T)\times V(T)$ such that~$(T,F)$
            is the maximal modular decomposition of~$G$,
            and let~$\mathbb{M}$ be the $\{\mathsf{ancestor},\ensuremath{\textsf{m}\text-\mathsf{edge}}\xspace\}$-structure
            modeling it with~$\mathbb{T}\sqsubset\mathbb{M}$ and $U_{\mathbb{T}}=U_{\mathbb{M}}$.
    \end{itemize}

Our \CMSO[2]-transduction is obtained by composing the three following transductions:
    \begin{itemize}[nosep]
        \item$\tau_1$: an \ensuremath{\operatorname{MSO}}\xspace-interpretation which outputs the $\{\ensuremath{\mathsf{edge}}\xspace,\ensuremath{\mathsf{SET}}\xspace\}$-structure $\mathbb{G}\sqcup\mathbb{S}$ from~$\mathbb{G}$;
        \item$\tau_2$: the non-deterministic \CMSO[2]-transduction given by \autoref{lem:transduce laminar tree induced by weakly-partitive family}
            which produces the $\{\ensuremath{\mathsf{edge}}\xspace,\ensuremath{\mathsf{SET}}\xspace,\mathsf{ancestor}\}$-structure $\mathbb{G}\sqcup\mathbb{S}\sqcup\mathbb{T}$ from $\mathbb{G}\sqcup\mathbb{S}$;
        \item$\tau_3$: an \ensuremath{\operatorname{MSO}}\xspace-interpretation which outputs the $\{\mathsf{ancestor},\ensuremath{\textsf{m}\text-\mathsf{edge}}\xspace\}$-structure $\mathbb{M}$ from $\mathbb{G}\sqcup\mathbb{S}\sqcup\mathbb{T}$.
    \end{itemize}

Note that any node with a child in $M$ must necessarily be labeled $\ensuremath{\mathsf{linear}}\xspace$ and hence:
    \begin{align*}
        \phi_{\mathsf{betweeness}}(t,x,y,z)&:= (x<_t y<_t z)\lor(z<_t y<_t x).
    \end{align*}
    Finally, the transduction forgets the predicate $\ensuremath{\mathsf{BIPART}}\xspace$ to produce the output $\mathbb{T}$.

Let $G$ be a connected, directed graph and $(H,F)$ an enriched split decomposition of $G$. Then the following hold:
    \begin{itemize}
        \item $uv\in E(G)$ if and only if\xspace there exists a directed path from $u$ to $v$ in $(H,F)$ on which $\textsf{c}$-edges and $\textsf{t}$-edges alternate;
        \item $v_{X}^Yv_{X'}^{Y'}$ is a $\textsf{c}$-edge in $(H,F)$ for vertices $v_{X}^Y,v_{X'}^{Y'}$ in the same component of $H$ if and only if\xspace there is $uu'\in E(G)$ such that $u\in Y$ and $u'\in Y'$.
    \end{itemize}

Let $G$ be a connected, directed graph represented by the $\{\ensuremath{\mathsf{edge}}\xspace\}$-structure $\mathbb{G}$. We associate the following objects with $G$:
    \begin{itemize}
        \item let $\ensuremath{\mathcal{B}}$ be the family of splits of $G$ and $\mathbb{B}$ the $\{\ensuremath{\mathsf{BIPART}}\xspace\}$-structure modeling the weakly-bipartitive bipartition system $(V(G),\ensuremath{\mathcal{B}})$ with $U_\mathbb{B}=V(G)$;
        \item let $T$ be the laminar tree induced by the weakly-bipartitive family $\ensuremath{\mathcal{B}}$ and let $\mathbb{T}$ be the $\{\ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace\}$-structure modeling it with $U_\mathbb{T}=V(T)$ and $L(T)=V(G)\subset U_\mathbb{T}$;
        \item let $(H,F)$ be the enriched canonical split decomposition of $G$ represented by the $\{\ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace,\ensuremath{\mathsf{c}\text-\mathsf{edge}}\xspace\}$-structure $\mathbb{H}$.
    \end{itemize}
    Our \CMSO[2]-transduction is obtained by composing the following transductions:
    \begin{itemize}
        \item $\tau_1$: an \ensuremath{\operatorname{MSO}}\xspace-interpretation which outputs the $\{\ensuremath{\mathsf{edge}}\xspace,\ensuremath{\mathsf{BIPART}}\xspace\}$-structure $\mathbb{G}\sqcup \mathbb{B}$ from $\mathbb{G}$;
        \item $\tau_2$: the non-deterministic \CMSO[2]-transduction from \autoref{lem:transduce laminar tree induced by weakly-bipartitive family} which outputs the $\{\ensuremath{\mathsf{edge}}\xspace,\ensuremath{\mathsf{BIPART}}\xspace, \ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace\}$-structure $\mathbb{G}\sqcup \mathbb{B}\sqcup \mathbb{T}$ on input $\mathbb{G}\sqcup \mathbb{S}$;
        \item $\tau_3$: an \ensuremath{\operatorname{MSO}}\xspace-transduction which produces the $\{\ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace,\ensuremath{\mathsf{c}\text-\mathsf{edge}}\xspace\}$-structure $\mathbb{H}$ from $\mathbb{G}\sqcup \mathbb{B}\sqcup \mathbb{T}$.
    \end{itemize}
    To define $\tau_1$ it is sufficient to observe that there is an \ensuremath{\operatorname{MSO}}\xspace-formula $\phi_{\ensuremath{\mathsf{BIPART}}\xspace}(X,Y)$ with two monadic free-variables $X$ and $Y$ such that $\phi_{\ensuremath{\mathsf{BIPART}}\xspace}$ is satisfied exactly when $\{X,Y\}$ is a split in $G$. As $\tau_2$ is constructed in \autoref{lem:transduce laminar tree induced by weakly-bipartitive family}, we are left with describing how to obtain $\tau_3$.
    We first need to find unique representative for the vertices in $V(H)$. Recall that $V(H)$ consists of two marker vertices $v_X^Y$ and $v_Y^X$ for every strong bipartition $\{X,Y\}\in \ensuremath{\mathcal{B}}$.
    For ease of notation, we use the name $v^{V(G)\setminus\{u\}}_{\{u\}}$ for the leaf $u\in V(G)$ of $T$. Additionally, we
    set $v_s^t:=v_X^Y$ and $v_t^s:=v_Y^X$ where $\{s,t\}\in E(T)$ is the edge for which $L(T_s)=X$ and $L(T_t)=Y$ where $T_s$ is the component of $T-e$ containing $s$ and $T_t$ the component containing $t$. We use the following atomic transductions to ensure unique representatives for all vertices in $V(H)$. We first guess a colouring $R$ which identifies one non-leaf element of $\mathbb{G}\sqcup \mathbb{B}\sqcup \mathbb{T}$ as root. We use this root element to interpret an auxiliary binary relation $\ensuremath{\mathsf{parent}}\xspace$ in the usual way. Now we copy the structure $\mathbb{G}\sqcup \mathbb{B}\sqcup \mathbb{T}$ once introducing the binary relation $\copyV[1]$ in which $\copyV[1](x,y)$ indicates that $x$ is the copy of $y$. Assume that $\{s,t\}$ is an edge in $T$ corresponding to a strong bipartition in $\ensuremath{\mathcal{B}}$ and $\ensuremath{\mathsf{parent}}\xspace(s,t)$ is satisfied. We use the original node $t$ to represent the marker $v_t^s$ and we use the copy of $t$ to represent the marker $v_s^t$. As every node has a unique parent in a rooted tree, for each marker the chosen representatives are unique. To express this we use the predicate $\ensuremath{\mathsf{marker}}\xspace(x,y,z)$ which expresses that $x$ is the representative of the marker $v_y^z$ defined as follows:
    $$\ensuremath{\mathsf{marker}}\xspace(x,y,z):= \Big(\ensuremath{\mathsf{parent}}\xspace(z,y)\land x=y\Big)\lor \Big(\ensuremath{\mathsf{parent}}\xspace(y,z)\land \copyV[1](x,z)\Big).$$
    We now filter the universe only keeping all representatives of markers (recall that markers $v_{\{v\}}^{V(G)\setminus\{v\}}$ are the original vertices of $G$). We are left with defining the two edge relations $\ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace$ and $\ensuremath{\mathsf{c}\text-\mathsf{edge}}\xspace$. To do so, we use the previously defined functional predicate $\ensuremath{\mathsf{leafset}}\xspace(t,s)$.

    First note that markers $v_t^s$ and $v_{t'}^{s'}$ are in the same component of $H$ if and only if\xspace $t=t'$. By \autoref{lem:edgesInSplitDecomposition} $v_t^sv_t^{s'}$ is an $\textsf{c}$-edge in $(H,F)$ if and only if\xspace there is an edge $uu'\in E(G)$ with $u\in L(T^t_s)$ and $u'\in L(T^t_{s'})$.
    Consequently, we can express $\ensuremath{\mathsf{c}\text-\mathsf{edge}}\xspace$ as follows:
    \begin{align*}
        \phi_{\ensuremath{\mathsf{c}\text-\mathsf{edge}}\xspace}(x,x'):=&\exists s \exists s' \exists t \exists y \exists y' \Big( \ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace(t,s)\land \ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace(t,s')\land \ensuremath{\mathsf{marker}}\xspace(x,t,s)\land
        \\*
        &\ensuremath{\mathsf{marker}}\xspace(x',t,s')\land
        y\in \ensuremath{\mathsf{leafset}}\xspace(t,s)\land y'\in \ensuremath{\mathsf{leafset}}\xspace(t,s') \land E(y,y') \Big).
    \end{align*}

    On the other hand, the
    $\ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace$-relation in $\mathbb{H}$ is the relation between pairs of markers and hence can be easily (re)-defined using the $\ensuremath{\mathsf{marker}}\xspace$ predicate by:
    $$\phi_{\ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace}(x,x'):=\exists y \exists z \big(\ensuremath{\mathsf{marker}}\xspace(x,y,z)\land \ensuremath{\mathsf{marker}}\xspace(x',z,y)\big).$$
    Finally, the transduction only keeps the relation $\ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace$ and $\ensuremath{\mathsf{c}\text-\mathsf{edge}}\xspace$.

Let $G$ be a connected, directed graph represented by the $\{\ensuremath{\mathsf{edge}}\xspace\}$-structure $\mathbb{G}$. We associate the following objects with $G$:
    \begin{itemize}
        \item let $\ensuremath{\mathcal{B}}$ be the family of splits of $G$ and $\mathbb{B}$ the $\{\ensuremath{\mathsf{BIPART}}\xspace\}$-structure modeling the weakly-bipartitive bipartition system $(V(G),\ensuremath{\mathcal{B}})$ with $U_\mathbb{B}=V(G)$;
        \item let $T$ be the laminar tree induced by the weakly-bipartitive family $\ensuremath{\mathcal{B}}$ and let $\mathbb{T}$ be the $\{\ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace\}$-structure modeling it with $U_\mathbb{T}=V(T)$ and $L(T)=V(G)\subset U_\mathbb{T}$;
        \item let $(H,F)$ be the enriched canonical split decomposition of $G$ represented by the $\{\ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace,\ensuremath{\mathsf{c}\text-\mathsf{edge}}\xspace\}$-structure $\mathbb{H}$.
    \end{itemize}

Our \CMSO[2]-transduction is obtained by composing the following transductions:
    \begin{itemize}
        \item $\tau_1$: an \ensuremath{\operatorname{MSO}}\xspace-interpretation which outputs the $\{\ensuremath{\mathsf{edge}}\xspace,\ensuremath{\mathsf{BIPART}}\xspace\}$-structure $\mathbb{G}\sqcup \mathbb{B}$ from $\mathbb{G}$;
        \item $\tau_2$: the non-deterministic \CMSO[2]-transduction from \autoref{lem:transduce laminar tree induced by weakly-bipartitive family} which outputs the $\{\ensuremath{\mathsf{edge}}\xspace,\ensuremath{\mathsf{BIPART}}\xspace, \ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace\}$-structure $\mathbb{G}\sqcup \mathbb{B}\sqcup \mathbb{T}$ on input $\mathbb{G}\sqcup \mathbb{S}$;
        \item $\tau_3$: an \ensuremath{\operatorname{MSO}}\xspace-transduction which produces the $\{\ensuremath{\mathsf{t}\text-\mathsf{edge}}\xspace,\ensuremath{\mathsf{c}\text-\mathsf{edge}}\xspace\}$-structure $\mathbb{H}$ from $\mathbb{G}\sqcup \mathbb{B}\sqcup \mathbb{T}$.
    \end{itemize}

Let $G$ be a connected graph and let $H$ be its skeleton graph. Then the following hold:
  \begin{enumerate}
  \item two vertices $x$ and $y$ of $G$ are adjacent if and only if there is an alternating path between $x$ and $y$ in $H$;
  \item the bipartitive tree of $\ensuremath{\mathcal{B}_\mathsf{join}^G}$ can be obtained from $H$ by contracting the graphs $G_u$, except vertices of $G$, and considering the
    $\mathsf{t}$-edges as its set of edges.
  \end{enumerate}

Let $V$ be a finite set of size at least $3$. Then the following hold:
   \begin{enumerate}
   \item for every two-graph $(V,\Delta)$, the graph $H(\Delta,x)$ is such that $\Omega(H(\Delta,x))=(V,\Delta)$;
   \item two graphs $G$ and $H$ with vertex set $V$ are Seidel equivalent if and only if $\Omega(G)=\Omega(H)$.
   \end{enumerate}
